import { compareHash, generateHash } from './extras'

describe('password hashing compatibility', () => {
    it('accepts an existing bcrypt 5 hash and rejects the wrong password', async () => {
        // Generated by bcrypt 5.1.1; upgrading must not require resetting user passwords.
        const legacyHash = '$2b$04$5FicjiuYszDbF8N6.gxUYuM5v/P/mQcGJIk1XeOmehsC8CwjQNfcO'
        expect(await compareHash('legacy-test-password', legacyHash)).toBe(true)
        expect(await compareHash('wrong-password', legacyHash)).toBe(false)
    })

    it('creates a new hash that authenticates only the original password', async () => {
        const hash = await generateHash('new-test-password')
        expect(hash).not.toBe('new-test-password')
        expect(await compareHash('new-test-password', hash)).toBe(true)
        expect(await compareHash('wrong-password', hash)).toBe(false)
    })
})
